def normalizar_nombre(nombre):
    """Normaliza nombre de equipo para comparación"""
    # Convertir a minúsculas
    nombre = str(nombre).lower().strip()
    # Quitar acentos/diacríticos
    nombre = unicodedata.normalize('NFKD', nombre)
    nombre = ''.join([c for c in nombre if not unicodedata.combining(c)])
    # Remover puntuación y caracteres no alfanuméricos (mantener espacios y números)
    nombre = re.sub(r"[^a-z0-9\s]", " ", nombre)
    # Reemplazos comunes de prefijos/sufijos y tokens de clubes
    replacements = {
        ' fc ': ' ',
        ' sc ': ' ',
        ' afc ': ' ',
        ' sv ': ' ',
        ' vfb ': ' ',
        ' vfl ': ' ',
        ' fsv ': ' ',
        ' tsg ': ' ',
        ' rb ': ' ',
        ' cf ': ' ',
        ' cd ': ' ',
        ' ac ': ' ',
        ' as ': ' ',
        ' u19 ': ' ',
        ' u21 ': ' ',
        ' b ': ' ',
        ' ii': ' 2',
        ' united': '',
        ' city': '',
        ' town': '',
        # normalizaciones específicas frecuentes
        ' atletico ': ' atletico ',
        ' saint ': ' st ',
        ' santo ': ' st ',
        ' santos ': ' st ',
        ' de la coruna': ' deportivo',
        ' la coruna': ' la coruna',
        ' guimaraes': ' guimaraes',
    }
    # aplicar reemplazos con espacios acolchados para evitar coincidencias parciales indeseadas
    padded = f" {nombre} "
    for old, new in replacements.items():
        padded = padded.replace(old, new)
    nombre = padded.strip()
    # Colapsar espacios múltiples
    nombre = re.sub(r"\s+", " ", nombre).strip()
    return nombre


def buscar_resultado(partido):
    """Busca el resultado de un partido"""
    # Primero intentar búsqueda exacta
    if partido in RESULTADOS:
        return RESULTADOS[partido]
    
    # Buscar con normalización
    partido_norm = normalizar_nombre(partido)
    for key, value in RESULTADOS.items():
        if normalizar_nombre(key) == partido_norm:
            return value
    
    # Buscar parcial (si contiene los equipos)
    partes = partido.split(' vs ')
    if len(partes) == 2:
        local = normalizar_nombre(partes[0])
        visitante = normalizar_nombre(partes[1])
        
        for key, value in RESULTADOS.items():
            key_partes = key.split(' vs ')
            if len(key_partes) == 2:
                key_local = normalizar_nombre(key_partes[0])
                key_visitante = normalizar_nombre(key_partes[1])
                
                # Verificar si coinciden los equipos
                if (local in key_local or key_local in local) and \
                   (visitante in key_visitante or key_visitante in visitante):
                    return value
    
    return None


def calcular_total_goles(score):
    """Calcula el total de goles de un score"""
    if pd.isna(score) or score is None:
        return None
    
    try:
        partes = str(score).split('-')
        return int(partes[0]) + int(partes[1])
    except:
        return None


def calcular_acierto(row):
    """Determina si la apuesta acertó"""
    if pd.isna(row.get('Score')) or pd.isna(row.get('Total_Goles')):
        return None
    
    mercado = row.get('Mercado', '')
    total_goles = row['Total_Goles']
    
    if 'Over' in mercado:
        linea = float(mercado.replace('Over ', '').replace('Under ', ''))
        return 'Sí' if total_goles > linea else 'No'
    elif 'Under' in mercado:
        linea = float(mercado.replace('Over ', '').replace('Under ', ''))
        return 'Sí' if total_goles < linea else 'No'
    
    return None


def actualizar_archivo(archivo_path):
    """Actualiza un archivo CSV con los resultados encontrados"""
    df = pd.read_csv(archivo_path)
    
    # Verificar si ya tiene columnas de resultados
    if 'Score' not in df.columns:
        df['Score'] = None
    if 'Total_Goles' not in df.columns:
        df['Total_Goles'] = None
    if 'Acerto' not in df.columns:
        df['Acerto'] = None
    
    actualizados = 0
    
    for idx, row in df.iterrows():
        # Solo procesar si no tiene score
        if pd.isna(row['Score']):
            partido = row['Partido']
            resultado = buscar_resultado(partido)
            
            if resultado:
                df.at[idx, 'Score'] = resultado
                df.at[idx, 'Total_Goles'] = calcular_total_goles(resultado)
                df.at[idx, 'Acerto'] = calcular_acierto(df.loc[idx])
                actualizados += 1
    
    if actualizados > 0:
        df.to_csv(archivo_path, index=False)
        print(f"  ✅ {archivo_path.name}: {actualizados} resultados agregados")
    else:
        print(f"  ⚪ {archivo_path.name}: sin cambios")
    
    return actualizados


def main():
    print("=" * 60)
    print("ACTUALIZANDO ARCHIVOS CON RESULTADOS ENCONTRADOS")
    print("=" * 60)
    print(f"\nResultados disponibles: {len(RESULTADOS)}")
    print()
    
    # Buscar todos los archivos _con_resultados.csv en la nueva carpeta
    archivos = list(Path('historical_con_resultados').glob('*_con_resultados.csv'))
    archivos.sort()
    
    total_actualizados = 0
    
    for archivo in archivos:
        actualizados = actualizar_archivo(archivo)
        total_actualizados += actualizados
    
    print()
    print("=" * 60)
    print(f"TOTAL: {total_actualizados} registros actualizados")
    print("=" * 60)
    
    # Mostrar estado final
    print("\nEstado final:")
    for archivo in archivos:
        df = pd.read_csv(archivo)
        con_score = df['Score'].notna().sum()
        sin_score = df['Score'].isna().sum()
        print(f"  {archivo.name}: {con_score} con resultado, {sin_score} sin resultado")


if __name__ == "__main__":
    main()
